files.content:
:root {
  --bg: #1e1e2f;
  --card: #2d2d44;
  --accent: #ff9f43;
  --accent-2: #54a0ff;
  --text: #f0f0f5;
  --muted: #a0a0b8;
  --hunger: #ff6b6b;
  --happiness: #feca57;
  --energy: #48dbfb;
  --radius: 16px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  font-size: 16px;
  background: radial-gradient(circle at 30% 20%, #2a2a40, var(--bg));
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

.card {
  background: var(--card);
  border-radius: var(--radius);
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.card-header {
  text-align: center;
}

h1 {
  font-size: 2rem;
  letter-spacing: 1px;
  color: var(--accent);
}

.mood {
  font-size: 1.1rem;
  color: var(--muted);
  margin-top: 4px;
  min-height: 1.4em;
}

/* Pet stage */
.pet-stage {
  display: flex;
  justify-content: center;
  padding: 8px 0;
}

.pet {
  position: relative;
  width: 140px;
  height: 140px;
  transition: transform 0.2s ease;
}

.pet.happy {
  animation: bounce 0.6s ease infinite alternate;
}

@keyframes bounce {
  from { transform: translateY(0); }
  to { transform: translateY(-8px); }
}

.ear {
  position: absolute;
  top: 0;
  width: 32px;
  height: 40px;
  background: var(--accent);
  border-radius: 50% 50% 0 0;
  z-index: 1;
}
.ear.left { left: 14px; transform: rotate(-15deg); }
.ear.right { right: 14px; transform: rotate(15deg); }

.face {
  position: absolute;
  top: 20px;
  left: 20px;
  width: 100px;
  height: 80px;
  background: var(--accent);
  border-radius: 50% 50% 45% 45%;
  z-index: 2;
}

.eye {
  position: absolute;
  top: 28px;
  width: 14px;
  height: 14px;
  background: #1e1e2f;
  border-radius: 50%;
}
.eye.left { left: 22px; }
.eye.right { right: 22px; }

.eye::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 5px;
  height: 5px;
  background: #fff;
  border-radius: 50%;
}

.mouth {
  position: absolute;
  bottom: 16px;
  left: 50%;
  transform: translateX(-50%);
  width: 24px;
  height: 10px;
  border-bottom: 3px solid #1e1e2f;
  border-radius: 0 0 50% 50%;
}

.pet.sad .mouth {
  border-bottom: none;
  border-top: 3px solid #1e1e2f;
  border-radius: 50% 50% 0 0;
  bottom: 12px;
}

.cheek {
  position: absolute;
  top: 42px;
  width: 12px;
  height: 8px;
  background: rgba(255, 107, 107, 0.4);
  border-radius: 50%;
}
.cheek.left { left: 8px; }
.cheek.right { right: 8px; }

.body {
  position: absolute;
  bottom: 0;
  left: 30px;
  width: 80px;
  height: 60px;
  background: var(--accent);
  border-radius: 40% 40% 30% 30%;
  z-index: 1;
}

.foot {
  position: absolute;
  bottom: 0;
  width: 28px;
  height: 16px;
  background: var(--accent);
  border-radius: 50%;
  z-index: 0;
}
.foot.left { left: 22px; }
.foot.right { right: 22px; }

/* Stats */
.stats {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.stat-label {
  display: flex;
  justify-content: space-between;
  font-size: 1rem;
  margin-bottom: 6px;
  color: var(--text);
}

.stat-value {
  font-weight: 600;
  color: var(--muted);
}

.bar {
  width: 100%;
  height: 14px;
  background: #1e1e2f;
  border-radius: 8px;
  overflow: hidden;
}

.fill {
  height: 100%;
  border-radius: 8px;
  transition: width 0.3s ease;
}
.fill.hunger { background: var(--hunger); }
.fill.happiness { background: var(--happiness); }
.fill.energy { background: var(--energy); }

/* Buttons */
.actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}

.action-btn {
  flex: 1 1 0;
  min-width: 90px;
  padding: 14px 18px;
  font-size: 1.05rem;
  font-family: inherit;
  font-weight: 600;
  color: #1e1e2f;
  background: var(--accent);
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: transform 0.1s ease, filter 0.15s ease, box-shadow 0.15s ease;
}

.action-btn:hover {
  filter: brightness(1.1);
  box-shadow: 0 4px 12px rgba(255, 159, 67, 0.4);
}

.action-btn:focus-visible {
  outline: 3px solid var(--accent-2);
  outline-offset: 3px;
}

.action-btn:active {
  transform: scale(0.96);
}

.action-btn.play { background: var(--accent-2); }
.action-btn.play:hover { box-shadow: 0 4px 12px rgba(84, 160, 255, 0.4); }

.action-btn.sleep { background: #a29bfe; }
.action-btn.sleep:hover { box-shadow: 0 4px 12px rgba(162, 155, 254, 0.4); }

@media (max-width: 360px) {
  .card { padding: 24px 16px; }
  h1 { font-size: 1.6rem; }
  .action-btn { min-width: 70px; padding: 12px 10px; font-size: 0.95rem; }
  .pet { transform: scale(0.85); }
}

(function () {
  'use strict';

  var state = {
    hunger: 70,
    happiness: 70,
    energy: 70
  };

  var els = {
    mood: document.getElementById('mood'),
    pet: document.getElementById('pet'),
    hungerFill: document.getElementById('hunger-fill'),
    happinessFill: document.getElementById('happiness-fill'),
    energyFill: document.getElementById('energy-fill'),
    hungerBar: document.getElementById('hunger-bar'),
    happinessBar: document.getElementById('happiness-bar'),
    energyBar: document.getElementById('energy-bar'),
    hungerValue: document.getElementById('hunger-value'),
    happinessValue: document.getElementById('happiness-value'),
    energyValue: document.getElementById('energy-value'),
    feedBtn: document.getElementById('feed-btn'),
    playBtn: document.getElementById('play-btn'),
    sleepBtn: document.getElementById('sleep-btn')
  };

  function clamp(value) {
    return Math.max(0, Math.min(100, value));
  }

  function moodFromState() {
    var avg = (state.hunger + state.happiness + state.energy) / 3;
    if (state.hunger < 25) return 'So hungry...';
    if (state.energy < 25) return 'So sleepy...';
    if (state.happiness < 25) return 'Feeling sad...';
    if (avg > 75) return 'Feeling great!';
    if (avg > 50) return 'Feeling okay.';
    return 'Needs some care.';
  }

  function render() {
    var mood = moodFromState();
    els.mood.textContent = mood;

    els.hungerFill.style.width = state.hunger + '%';
    els.happinessFill.style.width = state.happiness + '%';
    els.energyFill.style.width = state.energy + '%';

    els.hungerBar.setAttribute('aria-valuenow', state.hunger);
    els.happinessBar.setAttribute('aria-valuenow', state.happiness);
    els.energyBar.setAttribute('aria-valuenow', state.energy);

    els.hungerValue.textContent = state.hunger + '%';
    els.happinessValue.textContent = state.happiness + '%';
    els.energyValue.textContent = state.energy + '%';

    els.pet.classList.toggle('happy', mood === 'Feeling great!');
    els.pet.classList.toggle('sad', state.happiness < 25 || state.hunger < 25 || state.energy < 25);
  }

  function feed() {
    state.hunger = clamp(state.hunger + 15);
    state.energy = clamp(state.energy - 5);
    render();
  }

  function play() {
    state.happiness = clamp(state.happiness + 15);
    state.energy = clamp(state.energy - 10);
    state.hunger = clamp(state.hunger - 5);
    render();
  }

  function sleep() {
    state.energy = clamp(state.energy + 20);
    state.hunger = clamp(state.hunger - 5);
    render();
  }

  els.feedBtn.addEventListener('click', feed);
  els.playBtn.addEventListener('click', play);
  els.sleepBtn.addEventListener('click', sleep);

  render();
})();
